import {greeceRangeDate,greeceDateInput} from '../../../shared/greece-time.mjs';
import {ownerShiftFields,ownerShiftSummaryFields,ownerShiftTransactionFields,ownerSaleLineFields,ownerShiftDifferenceFields,ownerPaymentSummaryFields,ownerPaymentMovementFields,businessPictureFields} from '../../../shared/backoffice-staff-company-owner-reports.mjs';
import {finishBusinessPictureRow} from '../../src/business-picture-totals.js';
const base={scope:'COMPANY',companyId:'a'},today=greeceDateInput(),first=today.slice(0,7)+'-01';
