 if(kind==='detail'){const header=shift(),tx={...financialFields(ownerShiftTransactionFields),id:'tx',type:'SALE_CASH',amount:0,occurredAt:header.openedAt,createdAt:header.openedAt,description:'Own sale',productSummary:'1× Product',saleLines:[{...financialFields(ownerSaleLineFields),id:'line',productId:null,description:'Historical product',quantity:1,unitPrice:0,lineTotal:0}]};return{...base,shift:header,transactions:[tx],categories:[{category:'Category',quantity:1,revenue:0,sales:1}],paymentMethods:[{method:'CASH',amount:0,count:1}],sales:{count:1,total:0,average:0,firstAt:header.openedAt,lastAt:header.openedAt},difference:{...financialFields(ownerShiftDifferenceFields),formula:'Native cash formula'},alerts:[{kind:'OPENING_VARIANCE',amount:0,label:'Native alert',transactionId:null}],sourceStatus:{vatFiscal:false,note:'Χωρίς φορολογική πηγή ΦΠΑ.'},window:{transactionLimit:10000,lineLimit:10000}}}
